package ultra.downloads;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class NativeStreamsTest {
 public static class Data{public List<Object> f=new ArrayList<>();}
 public static class Format{public String f,g;public int e,h;public long p=123,q=4000000;public List<Object>s=new ArrayList<>();Format(int tag,int bitrate,String mime,String url){e=tag;h=bitrate;g=mime;f=url;}}
 static String url="https://rr1---sn-test.googlevideo.com/videoplayback?expire=4102444800&c=ANDROID_MUSIC";
 Hooks.Probe oldProbe;@After public void restoreProbe(){Hooks.probe=oldProbe;}
 @Before public void clear(){oldProbe=Hooks.probe;Hooks.probe=new Hooks.Probe(){public void check(Hooks.Audio a){}};synchronized(NativeStreams.cache){NativeStreams.cache.clear();NativeStreams.headers.clear();}}
 @Test public void exactNativeResponseIdentityOnly(){Data d=new Data();d.f.add(new Format(251,160000,"audio/webm; codecs=opus",url));NativeStreams.capture("abcdefghijk",d);assertSame(d,NativeStreams.get("abcdefghijk"));assertNull(NativeStreams.get("bcdefghijkl"));NativeStreams.capture("bad",d);assertNull(NativeStreams.get("bad"));NativeStreams.invalidate("abcdefghijk");assertNull(NativeStreams.get("abcdefghijk"));}
 @Test public void highestSourceBitrateByDefaultNotFirstFormat()throws Exception{Data d=new Data();d.f.add(new Format(140,128000,"audio/mp4",url));d.f.add(new Format(251,180000,"audio/webm; codecs=opus",url));d.f.add(new Format(141,256000,"audio/mp4",url));Hooks.Audio a=NativeStreams.select(d,null,"best");assertEquals(256000,a.bitrate);assertEquals("141:123",a.key);assertEquals(4000000,a.size);assertEquals(128000,NativeStreams.select(d,null,"saver").bitrate);assertEquals(180000,NativeStreams.select(d,"251:123","best").bitrate);assertNull(NativeStreams.select(d,"999:123","best"));}
 @Test public void protectedExpiredCipherAndOtherHostsRejected()throws Exception{Data d=new Data();Format protectedF=new Format(141,256000,"audio/mp4",url);protectedF.s.add(1);d.f.add(protectedF);d.f.add(new Format(140,128000,"audio/mp4",""));d.f.add(new Format(251,180000,"audio/webm","https://attacker.invalid/audio"));d.f.add(new Format(250,100000,"audio/webm",url.replace("4102444800","1")));d.f.add(new Format(18,1000000,"video/mp4",url));assertNull(NativeStreams.select(d,null,"best"));}
 @Test public void actualHostProtoFieldsAndLongContentLengthWork()throws Exception{Object d=NativeModels.fresh("com.google.protos.youtube.api.innertube.StreamingDataOuterClass$StreamingData");Object f=NativeModels.fresh("blvt");NativeModels.set(f,"e",251);NativeModels.set(f,"h",180000);NativeModels.set(f,"g","audio/webm; codecs=opus");NativeModels.set(f,"f",url);NativeModels.set(f,"p",42L);NativeModels.set(f,"q",5000000L);Object original=Hooks.field(d,"f");Class<?> base=Class.forName("bhbk");java.lang.reflect.Method copy=base.getDeclaredMethod("mutableCopy",Class.forName("bhbw"));copy.setAccessible(true);Object list=copy.invoke(null,original);((List)list).add(f);NativeModels.set(d,"f",list);NativeStreams.capture("abcdefghijk",d);Hooks.Audio a=Hooks.resolve("abcdefghijk",false,null,"best");assertEquals(5000000L,a.size);assertEquals(180000,a.bitrate);assertEquals("251:42",a.key);}
 @Test public void boundedMemoryAndNoUnrelatedHeaders(){for(int n=0;n<30;n++){Data d=new Data();d.f.add(new Format(251,180000,"audio/webm",url));NativeStreams.capture(String.format("song%07d",n),d);}assertEquals(24,NativeStreams.cache.size());Map<String,String> h=new HashMap<>();h.put("Authorization","test-only-placeholder");h.put("X-Goog-Visitor-Id","test-visitor");h.put("Unrelated-Header","not copied");NativeStreams.captureHeaders(h);assertEquals(2,NativeStreams.headers.size());assertFalse(NativeStreams.headers.containsKey("Unrelated-Header"));}
 @Test public void topInsetOnlyUncoveredAreaAndFormatLabels(){assertEquals(32,DownloadsScreen.uncoveredTop(32,0));assertEquals(8,DownloadsScreen.uncoveredTop(32,24));assertEquals(0,DownloadsScreen.uncoveredTop(32,32));assertEquals(0,DownloadsScreen.uncoveredTop(24,50));Library.Item i=new Library.Item();i.mime="audio/webm";i.bitrate=181000;assertEquals(" • WebM 181 kbps",DownloadsScreen.qualityLabel(i));}
 @Test public void visitorOnlyCapturePreservesNativeAuthorization(){Map<String,String> first=new HashMap<>();first.put("Authorization","test-native-session");first.put("X-Goog-AuthUser","1");NativeStreams.captureHeaders(first);NativeStreams.captureHeaders(Collections.singletonMap("X-Goog-Visitor-Id","new-visitor"));assertEquals("test-native-session",NativeStreams.requestHeaders().get("Authorization"));assertEquals("1",NativeStreams.requestHeaders().get("X-Goog-AuthUser"));assertEquals("new-visitor",NativeStreams.requestHeaders().get("X-Goog-Visitor-Id"));}
}
